-- Comentarios da CLT, lote 11 (arts. 511 a 550, sem 536, que nao tem caput vigente). Autorizado pela Jessica em 21/10/2026.
-- Redigidos so a partir do texto do artigo e dos dispositivos filhos no banco (sem jurisprudencia ou doutrina).
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='clt' and numero between 511 and 550;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a
from (values
(511,'','Associação sindical e categorias','É lícita a associação para fins de estudo, defesa e coordenação dos seus interesses econômicos ou profissionais de todos os que, como empregadores, empregados, agentes ou trabalhadores autônomos ou profissionais liberais exerçam, respectivamente, a mesma atividade ou profissão ou atividades ou profissões similares ou conexas. O § 1º dispõe que a solidariedade de interesses econômicos dos que empreendem atividades idênticas, similares ou conexas constitui o vínculo social básico que se denomina categoria econômica. O § 2º trata da similitude de condições de vida oriunda da profissão ou trabalho em comum, em situação de emprego na mesma atividade econômica ou em atividades econômicas similares ou conexas, nos termos do parágrafo. O § 3º define categoria profissional diferenciada como a que se forma dos empregados que exerçam profissões ou funções diferenciadas por força de estatuto profissional especial ou em consequência de condições de vida singulares. O § 4º dispõe que os limites de identidade, similaridade ou conexidade fixam as dimensões dentro das quais a categoria econômica ou profissional é homogênea e a associação é natural.'),
(512,'','Reconhecimento como sindicato','Somente as associações profissionais constituídas para os fins e na forma do artigo anterior e registradas de acordo com o art. 558 podem ser reconhecidas como Sindicatos e investidas nas prerrogativas definidas na lei.'),
(513,'','Prerrogativas dos sindicatos','São prerrogativas dos sindicatos: representar, perante as autoridades administrativas e judiciárias, os interesses gerais da respectiva categoria ou profissão liberal ou interesses individuais dos associados relativos à atividade ou profissão exercida (alínea a); celebrar contratos coletivos de trabalho (alínea b); eleger ou designar os representantes da respectiva categoria ou profissão liberal (alínea c); colaborar com o Estado, como órgãos técnicos e consultivos, no estudo e solução dos problemas que se relacionam com a respectiva categoria ou profissão liberal (alínea d); e impor contribuições a todos aqueles que participam das categorias econômicas ou profissionais ou das profissões liberais representadas (alínea e). O artigo traz ainda parágrafo único relativo aos sindicatos, nos termos do dispositivo.'),
(514,'','Deveres dos sindicatos','São deveres dos sindicatos: colaborar com os poderes públicos no desenvolvimento da solidariedade social (alínea a); fundar e manter escolas de alfabetização e prevocacionais (alínea b); e promover a conciliação nos dissídios de trabalho (alínea c). O parágrafo único dispõe que os sindicatos de empregados têm, outrossim, o dever de promover a fundação de cooperativas de consumo e de crédito (alínea a), manter serviços de assistência judiciária para os associados (alínea b) e, sempre que possível, e de acordo com as suas possibilidades, manter no seu quadro de pessoal, em convênio com entidades assistenciais ou por conta própria, um assistente social com as atribuições específicas previstas na alínea d.'),
(515,'','Requisitos para o reconhecimento como sindicato','As associações profissionais devem satisfazer os seguintes requisitos para serem reconhecidas como sindicatos: reunião de um terço, no mínimo, de empresas legalmente constituídas, sob a forma individual ou de sociedade, se se tratar de associação de empregadores, ou de um terço dos que integrem a mesma categoria ou exerçam a mesma profissão, nos termos da alínea a; duração de 3 (três) anos para o mandato da diretoria (alínea b); e exercício do cargo de presidente por brasileiro nato, e dos demais cargos de administração e representação por brasileiros (alínea c). O parágrafo único dispõe que o ministro do Trabalho, Indústria e Comércio pode, excepcionalmente, reconhecer como sindicato a associação cujo número de associados seja inferior ao terço a que se refere a alínea a.'),
(516,'','Unicidade sindical','Não será reconhecido mais de um Sindicato representativo da mesma categoria econômica ou profissional, ou profissão liberal, em uma dada base territorial.'),
(517,'','Base territorial e espécies de sindicatos','Os sindicatos podem ser distritais, municipais, intermunicipais, estaduais e interestaduais. Excepcionalmente, e atendendo às peculiaridades de determinadas categorias ou profissões, o ministro do Trabalho, Indústria e Comércio pode autorizar o reconhecimento de sindicatos nacionais. O § 1º dispõe que o ministro outorga e delimita a base territorial do sindicato. O § 2º dispõe que, dentro da base territorial que lhe for determinada, é facultado ao sindicato instituir delegacias ou seções para melhor proteção dos associados e da categoria econômica ou profissional ou profissão liberal representada.'),
(518,'','Pedido de reconhecimento do sindicato','O pedido de reconhecimento é dirigido ao ministro do Trabalho, Indústria e Comércio, instruído com exemplar ou cópia autenticada dos estatutos da associação. O § 1º dispõe que os estatutos devem conter: a denominação e a sede da associação (alínea a); a categoria econômica ou profissional ou a profissão liberal cuja representação é requerida (alínea b); a afirmação de que a associação agirá como órgão de colaboração com os poderes públicos e as demais associações no sentido da solidariedade social, nos termos da alínea c; as atribuições, o processo eleitoral e das votações, os casos de perda de mandato e de substituição dos administradores (alínea d); o modo de constituição e administração do patrimônio social e o destino que lhe será dado no caso de dissolução (alínea e); e as condições em que se dissolverá a associação (alínea f). O § 2º dispõe que o processo de reconhecimento é regulado em instruções baixadas pelo ministro do Trabalho, Indústria e Comércio.'),
(519,'','Investidura sindical','A investidura sindical é conferida sempre à associação profissional mais representativa, a juízo do Ministro do Trabalho, constituindo elementos para essa apreciação, entre outros, o número de associados (alínea a), os serviços sociais fundados e mantidos (alínea b) e o valor do patrimônio (alínea c).'),
(520,'','Carta de reconhecimento','Reconhecida como sindicato a associação profissional, lhe é expedida carta de reconhecimento, assinada pelo ministro do Trabalho, Indústria e Comércio, na qual é especificada a representação econômica ou profissional conferida e mencionada a base territorial outorgada. O parágrafo único dispõe que o reconhecimento investe a associação nas prerrogativas do art. 513 e a obriga aos deveres do art. 514, cujo inadimplemento a sujeita às sanções da lei.'),
(521,'','Condições para o funcionamento do sindicato','São condições para o funcionamento do Sindicato: proibição de qualquer propaganda de doutrinas incompatíveis com as instituições e os interesses da Nação, bem como de candidaturas a cargos eletivos estranhos ao sindicato (alínea a); proibição de exercício de cargo eletivo cumulativamente com o de emprego remunerado pelo sindicato ou por entidade sindical de grau superior (alínea b); gratuidade do exercício dos cargos eletivos (alínea c); proibição de quaisquer atividades não compreendidas nas finalidades mencionadas no art. 511, inclusive as de caráter político-partidário (alínea d); e proibição de cessão gratuita ou remunerada da respectiva sede a entidade de índole político-partidária (alínea e). O parágrafo único trata do associado de sindicato de empregados, de trabalhadores autônomos ou de profissionais liberais que, para o exercício de mandato, tiver de se afastar do seu trabalho, hipótese em que pode lhe ser arbitrada pela assembleia geral uma gratificação, nos termos do parágrafo.'),
(522,'','Administração do sindicato','A administração do sindicato é exercida por uma diretoria constituída no máximo de sete e no mínimo de três membros e de um Conselho Fiscal composto de três membros, eleitos esses órgãos pela Assembleia Geral. O caput consta na fonte com a anotação "Vide ADPF 276", e este comentário não afirma o seu resultado. O § 1º dispõe que a diretoria elege, dentre os seus membros, o presidente do sindicato. O § 2º dispõe que a competência do Conselho Fiscal é limitada à fiscalização da gestão financeira do sindicato. O § 3º trata da atribuição exclusiva da Diretoria do Sindicato e dos Delegados Sindicais, a que se refere o art. 523, quanto à representação e à defesa dos interesses da entidade perante os poderes públicos e as empresas, nos termos do parágrafo.'),
(523,'','Delegados sindicais','Os Delegados Sindicais destinados à direção das delegacias ou seções instituídas na forma estabelecida no § 2º do art. 517 são designados pela diretoria dentre os associados radicados no território da correspondente delegacia.'),
(524,'','Deliberações da Assembleia Geral por escrutínio secreto','São sempre tomadas por escrutínio secreto, na forma estatutária, as deliberações da Assembleia Geral concernentes aos seguintes assuntos: eleição de associado para representação da respectiva categoria prevista em lei (alínea a); tomada e aprovação de contas da diretoria (alínea b); aplicação do patrimônio (alínea c); julgamento dos atos da Diretoria, relativos a penalidades impostas a associados (alínea d); e pronunciamento sobre relações ou dissídio de trabalho, caso em que as deliberações só são consideradas válidas quando a Assembleia tiver sido especialmente convocada para esse fim, nos termos da alínea e. O § 1º dispõe que a eleição para cargos de diretoria e conselho fiscal é realizada por escrutínio secreto, durante 6 (seis) horas contínuas, pelo menos, na sede do Sindicato, na de suas delegacias e seções e nos principais locais de trabalho, nos termos do parágrafo. O § 2º trata da Assembleia Eleitoral pública e permanente que se instala, concomitantemente ao término do prazo estipulado para a votação, com a mesa apuradora, nos termos do parágrafo. O § 3º dispõe que a mesa apuradora é presidida por membro do Ministério Público do Trabalho ou pessoa de notória idoneidade, designado nos termos do parágrafo. O § 4º dispõe que o pleito só é válido na hipótese de participarem da votação mais de 2/3 (dois terços) dos associados com capacidade para votar, e trata da nova eleição, dentro de 15 (quinze) dias, caso não obtido esse coeficiente, nos termos do parágrafo. O § 5º trata da hipótese em que não é atingido o coeficiente legal para eleição, caso em que o Ministério do Trabalho declara a vacância da administração, nos termos do parágrafo.'),
(525,'','Vedação de interferência na administração sindical','É vedada a pessoas físicas ou jurídicas, estranhas ao Sindicato, qualquer interferência na sua administração ou nos seus serviços. O parágrafo único dispõe que estão excluídos dessa proibição os delegados do Ministério do Trabalho, Indústria e Comércio, especialmente designados pelo ministro ou por quem o represente (alínea a), e os que, como empregados, exerçam cargos no Sindicato mediante autorização da Assembleia Geral (alínea b).'),
(526,'','Empregados do sindicato','Os empregados do Sindicato são nomeados pela diretoria respectiva ad referendum da Assembleia Geral, não podendo recair tal nomeação nos que estiverem nas condições previstas nos itens II, IV, V, VI, VII e VIII do art. 530 e, na hipótese de o nomeador haver sido dirigente sindical, também nas do item I do mesmo artigo. O § 2º dispõe que se aplicam ao empregado de entidade sindical os preceitos das leis de proteção do trabalho e de previdência social, inclusive o direito de associação em sindicato.'),
(527,'','Livro de registro do sindicato','Na sede de cada sindicato há um livro de registro, autenticado pelo funcionário competente do Ministério do Trabalho, Indústria e Comércio, e do qual devem constar, tratando-se de sindicato de empregadores, a firma, individual ou coletiva, ou a denominação das empresas e sua sede, o nome, idade, estado civil, nacionalidade e residência dos respectivos sócios, nos termos da alínea a; e, tratando-se de sindicato de empregados ou de agentes ou trabalhadores autônomos ou de profissionais liberais, além do nome, idade, estado civil, nacionalidade, profissão ou função e residência de cada associado, o estabelecimento ou lugar onde exerce a profissão ou função, nos termos da alínea b.'),
(528,'','Intervenção em entidade sindical','Ocorrendo dissídio ou circunstâncias que perturbem o funcionamento de entidade sindical ou motivos relevantes de segurança nacional, o Ministro do Trabalho e Previdência Social pode nela intervir, por intermédio de Delegado ou de Junta Interventora, com atribuições para administrá-la e executar ou propor as medidas necessárias para normalizar-lhe o funcionamento.'),
(529,'','Condições para o voto e para a investidura em cargo sindical','São condições para o exercício do direito do voto como para a investidura em cargo de administração ou representação econômica ou profissional: ter o associado mais de seis meses de inscrição no Quadro Social e mais de 2 (dois) anos de exercício da atividade ou da profissão (alínea a); ser maior de 18 (dezoito) anos (alínea b); e estar no gozo dos direitos sindicais (alínea c). O parágrafo único dispõe que é obrigatório aos associados o voto nas eleições sindicais.'),
(530,'','Impedimentos para cargos administrativos ou de representação sindical','Não podem ser eleitos para cargos administrativos ou de representação econômica ou profissional, nem permanecer no exercício desses cargos: os que não tiverem definitivamente aprovadas as suas contas de exercício em cargos de administração (inciso I); os que houverem lesado o patrimônio de qualquer entidade sindical (inciso II); os que não estiverem, desde dois (2) anos antes, pelo menos, no exercício efetivo da atividade ou da profissão dentro da base territorial do sindicato, ou no desempenho de representação econômica ou profissional (inciso III); os que tiverem sido condenados por crime doloso enquanto persistirem os efeitos da pena (inciso IV); os que não estiverem no gozo de seus direitos políticos (inciso V); e a hipótese de má conduta, devidamente comprovada (inciso VII).'),
(531,'','Eleição para cargos de diretoria e conselho fiscal','Nas eleições para cargos de diretoria e do conselho fiscal são considerados eleitos os candidatos que obtiverem maioria absoluta de votos em relação ao total dos associados eleitores. O § 1º trata da hipótese em que não concorre à primeira convocação maioria absoluta de eleitores, ou nenhum dos candidatos obtém essa maioria, com nova convocação para dia posterior, nos termos do parágrafo. O § 2º trata da hipótese em que há somente uma chapa registrada para as eleições, caso em que a assembleia pode, em última convocação, ser realizada duas horas após a primeira convocação, desde que do edital respectivo conste essa advertência. O § 3º dispõe que, concorrendo mais de uma chapa, o Ministério do Trabalho, Indústria e Comércio pode designar o presidente da sessão eleitoral, desde que o requeiram os associados que encabeçarem as respectivas chapas. O § 4º dispõe que o ministro do Trabalho, Indústria e Comércio expede instruções regulando o processo das eleições.'),
(532,'','Renovação da diretoria e posse','As eleições para a renovação da Diretoria e do Conselho Fiscal devem ser procedidas dentro do prazo máximo de 60 (sessenta) dias e mínimo de 30 (trinta) dias, antes do término do mandato dos dirigentes em exercício. O § 1º trata da hipótese em que não há protesto na ata da assembleia eleitoral ou recurso interposto por algum dos candidatos, dentro de 15 dias a contar da data das eleições, caso em que a posse da diretoria eleita independe da aprovação das eleições pelo Ministério, nos termos do parágrafo. O § 2º trata da competência da diretoria em exercício, dentro de 30 dias da realização das eleições, quanto à publicidade do resultado do pleito, nos termos do parágrafo. O § 3º trata da hipótese em que há protesto na ata da assembleia eleitoral ou recurso interposto dentro de 15 dias da realização das eleições, caso em que compete à diretoria em exercício encaminhar o processo eleitoral, nos termos do parágrafo. O § 4º dispõe que, não se verificando as hipóteses do parágrafo anterior, a posse da nova diretoria deve se verificar dentro de 30 dias subsequentes ao término do mandato da anterior. O § 5º dispõe que, ao assumir o cargo, o eleito presta, por escrito e solenemente, o compromisso de respeitar, no exercício do mandato, a Constituição, as leis vigentes e os estatutos da entidade.'),
(533,'','Associações sindicais de grau superior','Constituem associações sindicais de grau superior as federações e confederações organizadas nos termos da lei.'),
(534,'','Federações','É facultado aos Sindicatos, quando em número não inferior a 5 (cinco), desde que representem a maioria absoluta de um grupo de atividades ou profissões idênticas, similares ou conexas, organizarem-se em federação. O § 1º dispõe que, se já existir federação no grupo de atividades ou profissões em que deva ser constituída a nova entidade, a criação desta não pode reduzir a menos de 5 (cinco) o número de Sindicatos que àquela devam continuar filiados. O § 2º dispõe que as federações são constituídas por Estados, podendo o Ministro do Trabalho, Indústria e Comércio autorizar a constituição de Federações interestaduais ou nacionais. O § 3º trata da permissão a qualquer federação, para o fim de lhes coordenar os interesses, de agrupar os Sindicatos de determinado município ou região a ela filiados, nos termos do parágrafo.'),
(535,'','Confederações','As Confederações organizam-se com o mínimo de 3 (três) federações e têm sede na Capital da República. O § 1º trata da denominação das confederações formadas por federações de Sindicatos de empregadores, nos termos do parágrafo. O § 2º trata da denominação das confederações formadas por federações de Sindicatos de empregados, nos termos do parágrafo. O § 3º dispõe que se denomina Confederação Nacional das Profissões Liberais a reunião das respectivas federações. O § 4º dispõe que as associações sindicais de grau superior da Agricultura e Pecuária são organizadas na conformidade do que dispuser a lei que regular a sindicalização dessas atividades ou profissões.'),
(537,'','Reconhecimento de federações e confederações','O pedido de reconhecimento de uma federação é dirigido ao ministro do Trabalho, Indústria e Comércio, acompanhado de um exemplar dos respectivos estatutos e das cópias autenticadas das atas da assembleia de cada sindicato ou federação que autorizar a filiação. O § 1º dispõe que a organização das federações e confederações obedece às exigências contidas nas alíneas b e c do art. 515. O § 2º dispõe que a carta de reconhecimento das federações é expedida pelo ministro do Trabalho, Indústria e Comércio, na qual é especificada a coordenação econômica ou profissional conferida e mencionada a base territorial outorgada. O § 3º dispõe que o reconhecimento das confederações é feito por decreto do Presidente da República.'),
(538,'','Administração das federações e confederações','A administração das federações e confederações é exercida pelos seguintes órgãos: Diretoria (alínea a), Conselho de Representantes (alínea b) e Conselho Fiscal (alínea c). O § 1º dispõe que a Diretoria é constituída no mínimo de 3 (três) membros e de 3 (três) membros se compõe o Conselho Fiscal, os quais são eleitos pelo Conselho de Representantes com mandato por 3 (três) anos. O § 2º dispõe que só podem ser eleitos os integrantes dos grupos das federações ou dos planos das confederações, respectivamente. O § 3º dispõe que o Presidente da federação ou confederação é escolhido dentre os seus membros, pela Diretoria. O § 4º trata do Conselho de Representantes, formado pelas delegações dos Sindicatos ou das Federações filiadas, constituída cada delegação de 2 (dois) membros, com mandato por 3 (três) anos, cabendo 1 (um) voto a cada delegação. O § 5º dispõe que a competência do Conselho Fiscal é limitada à fiscalização da gestão financeira.'),
(539,'','Constituição e administração das federações','Para a constituição e administração das Federações são observadas, no que for aplicável, as disposições das Seções II e III do Capítulo.'),
(540,'','Direito de admissão no sindicato','A toda empresa ou indivíduo que exerçam respectivamente atividade ou profissão, desde que satisfaçam as exigências da lei, assiste o direito de ser admitido no sindicato da respectiva categoria. O § 1º dispõe que perde os direitos de associado o sindicalizado que, por qualquer motivo, deixar o exercício de atividade ou de profissão. O § 2º trata dos associados de Sindicatos de empregados, de agentes ou trabalhadores autônomos e de profissões liberais que forem aposentados, estiverem em desemprego ou falta de trabalho ou tiverem sido convocados para prestação de serviço militar, nos termos do parágrafo.'),
(541,'','Filiação a sindicato de profissão idêntica, similar ou conexa','Os que exercerem determinada atividade ou profissão onde não haja Sindicato da respectiva categoria, ou de atividade ou profissão similar ou conexa, podem filiar-se a Sindicato de profissão idêntica, similar ou conexa, existente na localidade mais próxima. O parágrafo único dispõe que o disposto no artigo se aplica aos Sindicatos em relação às respectivas federações, na conformidade do Quadro de Atividades e Profissões a que se refere o art. 577.'),
(542,'','Recurso contra ato lesivo da entidade sindical','De todo ato lesivo de direitos ou contrário à lei, emanado da Diretoria, do Conselho ou da Assembleia Geral da entidade sindical, pode qualquer exercente de atividade ou profissão recorrer, dentro de 30 dias, para a autoridade competente do Ministério do Trabalho, Indústria e Comércio.'),
(543,'','Garantias do empregado eleito para cargo de administração sindical','O empregado eleito para cargo de administração sindical ou representação profissional, inclusive junto a órgão de deliberação coletiva, não pode ser impedido do exercício de suas funções, nem transferido para lugar ou mister que lhe dificulte ou torne impossível o desempenho das suas atribuições sindicais. O § 1º dispõe que o empregado perde o mandato se a transferência for por ele solicitada ou voluntariamente aceita. O § 2º dispõe que se considera de licença não remunerada, salvo assentimento da empresa ou cláusula contratual, o tempo em que o empregado se ausentar do trabalho no desempenho das funções a que se refere o artigo. O § 3º trata da vedação da dispensa do empregado sindicalizado ou associado, a partir do momento do registro de sua candidatura a cargo de direção ou representação de entidade sindical ou de associação profissional, nos termos do parágrafo. O § 4º dispõe que se considera cargo de direção ou de representação sindical aquele cujo exercício ou indicação decorre de eleição prevista em lei. O § 5º trata da comunicação por escrito que a entidade sindical faz à empresa, dentro de 24 (vinte e quatro) horas, do dia e da hora do registro da candidatura do seu empregado e, em igual prazo, de sua eleição e posse, nos termos do parágrafo. O § 6º trata da empresa que, por qualquer modo, procurar impedir que o empregado se associe a sindicato, organize associação profissional ou sindical ou exerça os direitos inerentes à condição de sindicalizado, ficando sujeita à penalidade prevista no parágrafo.'),
(544,'','Preferências do empregado sindicalizado','É livre a associação profissional ou sindical, mas ao empregado sindicalizado é assegurada, em igualdade de condições, preferência: para a admissão nos trabalhos de empresa que explore serviços públicos ou mantenha contrato com os poderes públicos (inciso I); para ingresso em funções públicas ou assemelhadas, em caso de cessação coletiva de trabalho, por motivo de fechamento de estabelecimento (inciso II); nas concorrências para aquisição de casa própria, pelo Plano Nacional de Habitação ou por intermédio de quaisquer instituições públicas (inciso III); nos loteamentos urbanos ou rurais, promovidos pela União, por seus órgãos de administração direta ou indireta ou sociedades de economia mista (inciso IV); na locação ou compra de imóveis, de propriedade de pessoa de direito público ou sociedade de economia mista, quando sob ação de despejo em tramitação judicial (inciso V); na concessão de empréstimos simples concedidos pelas agências financeiras do Governo ou a ele vinculadas (inciso VI); na aquisição de automóveis, outros veículos e instrumentos relativos ao exercício da profissão, quando financiados pelas autarquias, sociedades de economia mista ou agências financeiras do Governo (inciso VII); e na concessão de bolsas de estudo para si ou para seus filhos, obedecida a legislação que regule a matéria (inciso IX).'),
(545,'','Desconto das contribuições devidas ao sindicato','Os empregadores ficam obrigados a descontar da folha de pagamento dos seus empregados, desde que por eles devidamente autorizados, as contribuições devidas ao sindicato, quando por este notificados. O parágrafo único dispõe que o recolhimento à entidade sindical beneficiária do importe descontado deve ser feito até o décimo dia subsequente ao do desconto, sob pena de juros de mora no valor de 10% (dez por cento) sobre o montante retido, nos termos do parágrafo.'),
(546,'','Preferência às empresas sindicalizadas','Às empresas sindicalizadas é assegurada preferência, em igualdade de condições, nas concorrências para exploração de serviços públicos, bem como nas concorrências para fornecimento às repartições federais, estaduais e municipais e às entidades paraestatais.'),
(547,'','Exigência da qualidade de sindicalizado','É exigida a qualidade de sindicalizado para o exercício de qualquer função representativa de categoria econômica ou profissional, em órgão oficial de deliberação coletiva, bem como para o gozo de favores ou isenções tributárias, salvo em se tratando de atividades não econômicas. O parágrafo único dispõe que, antes da posse ou exercício das funções a que alude o artigo anterior ou de concessão dos favores, é indispensável comprovar a sindicalização, ou oferecer prova, nos termos do parágrafo.'),
(548,'','Patrimônio das associações sindicais','Constituem o patrimônio das associações sindicais: as contribuições devidas aos Sindicatos pelos que participem das categorias econômicas ou profissionais ou das profissões liberais representadas pelas referidas entidades, sob a denominação de imposto sindical, nos termos da alínea a; as contribuições dos associados, na forma estabelecida nos estatutos ou pelas Assembleias Gerais (alínea b); os bens e valores adquiridos e as rendas produzidas pelos mesmos (alínea c); as doações e legados (alínea d); e as multas e outras rendas eventuais (alínea e).'),
(549,'','Aplicação da receita e bens imóveis das entidades sindicais','A receita dos sindicatos, federações e confederações só pode ter aplicação na forma prevista nos respectivos orçamentos anuais, obedecidas as disposições estabelecidas na lei e nos seus estatutos. O § 1º dispõe que, para alienação, locação ou aquisição de bens imóveis, as entidades sindicais ficam obrigadas a realizar avaliação prévia pela Caixa Econômica Federal ou pelo Banco Nacional da Habitação ou, ainda, por qualquer outra organização, nos termos do parágrafo. O § 2º dispõe que os bens imóveis das entidades sindicais não são alienados sem a prévia autorização das respectivas assembleias gerais, reunidas com a presença da maioria absoluta dos associados com direito a voto ou dos Conselhos de Representantes, nos termos do parágrafo. O § 3º trata da hipótese em que não é obtido o quorum estabelecido no parágrafo anterior, caso em que a matéria pode ser decidida em nova assembleia geral, reunida com qualquer número de associados com direito a voto, após o transcurso de 10 (dez) dias da primeira convocação. O § 4º dispõe que, nas hipóteses previstas nos §§ 2º e 3º, a decisão somente tem validade se adotada pelo mínimo de 2/3 (dois terços) dos presentes, em escrutínio secreto. O § 5º dispõe que, da deliberação da assembleia geral, concernente à alienação de bens imóveis, cabe recurso voluntário, dentro do prazo de 15 (quinze) dias, ao Ministro do Trabalho, com efeito suspensivo. O § 6º dispõe que a venda do imóvel é efetuada pela diretoria da entidade, após a decisão da Assembleia Geral ou do Conselho de Representantes, mediante concorrência pública, com edital publicado nos termos do parágrafo. O § 7º dispõe que os recursos destinados ao pagamento total ou parcelado dos bens imóveis adquiridos são consignados, obrigatoriamente, nos orçamentos anuais das entidades sindicais.'),
(550,'','Orçamentos das entidades sindicais','Os orçamentos das entidades sindicais são aprovados, em escrutínio secreto, pelas respectivas Assembleias Gerais ou Conselho de Representantes, até 30 (trinta) dias antes do início do exercício financeiro a que se referem, e contêm a discriminação da receita e da despesa, na forma das instruções e modelos expedidos pelo Ministério do Trabalho. O § 1º dispõe que os orçamentos, após a aprovação, são publicados, em resumo, no prazo de 30 (trinta) dias, contados da data da realização da respectiva Assembleia Geral ou da reunião do Conselho de Representantes, no Diário Oficial da União, quanto aos orçamentos das confederações, federações e sindicatos de base interestadual ou nacional, e no órgão de imprensa oficial do Estado ou Território ou jornal de grande circulação local, quanto aos orçamentos das federações estaduais e sindicatos distritais, municipais, intermunicipais e estaduais. O § 2º trata das dotações orçamentárias que se apresentarem insuficientes para o atendimento das despesas, ou não incluídas nos orçamentos correntes, que podem ser ajustadas ao fluxo dos gastos, mediante a abertura de créditos adicionais, nos termos do parágrafo. O § 3º dispõe que os créditos adicionais se classificam em suplementares, os destinados a reforçar dotações alocadas no orçamento (alínea a), e especiais, os destinados a incluir dotações no orçamento, a fim de fazer face às despesas para as quais não se tenha consignado crédito específico (alínea b). O § 4º dispõe que a abertura dos créditos adicionais depende da existência de receita para sua compensação, considerando-se, para esse efeito, desde que não comprometidos, o superavit financeiro apurado em balanço do exercício anterior, o excesso de arrecadação e a resultante da anulação parcial ou total de dotações alocadas no orçamento ou de créditos adicionais abertos no exercício. O § 5º dispõe que, para efeito orçamentário e contábil sindical, o exercício financeiro coincide com o ano civil, a ele pertencendo todas as receitas arrecadadas e as despesas compromissadas.')
) as v(n,t,c,a)
where l.codigo='clt' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente and l.texto ~ '^Art';
